/// has caused missed re-renders here before.
private func setIfChanged<T>(
    _ keyPath: ReferenceWritableKeyPath<AppState, [T]>, to value: [T],
    by same: (T, T) -> Bool
) {
    let current = self[keyPath: keyPath]
